@startuml
class Person {
  +personID : string
  +phoneNumber : string
  +keywords : string[]
}

class ResearchInstitution {
  +institutionCode : string
}

class ScientificArticle {
  +DOI : string
  +title : string
}

class PeerReviewedPaper extends ScientificArticle {
  +citationCount : int
}

class TechnicalReport extends ScientificArticle {
}

class AuthorPosition {
  +position : string
}

class Publisher {
  +name : string
}

class Journal {
  +name : string
  +impactFactor : float
}

Person "1" -- "1" ResearchInstitution : works for
Person "1" -- "*" ScientificArticle : author of
Person "0..*" -- "0..*" PeerReviewedPaper : reviews
ResearchInstitution "1" -- "*" TechnicalReport : publishes
Publisher "1" -- "*" Journal : publishes
ResearchInstitution "0..*" -- "0..*" Journal : subscribes to
PeerReviewedPaper "*" -- "1" Journal : published in
ScientificArticle "1" *-- "*" AuthorPosition
Person "1" -- "*" AuthorPosition : occupies position of
@enduml

